// Analyze document structure from Docling JSON output
const item = items[0].json;
const doc = item.content;

// Count different element types
const elements = doc.main_text || [];
const tables = doc.tables || [];
const figures = doc.figures || [];

// Extract headings
const headings = [];
if (elements) {
  for (const el of elements) {
    if (el.type && el.type.includes('heading')) {
      headings.push({
        level: el.level || 'unknown',
        text: el.text || ''
      });
    }
  }
}

// Calculate statistics
const stats = {
  total_pages: doc.pages ? doc.pages.length : 0,
  total_elements: elements.length,
  total_tables: tables.length,
  total_figures: figures.length,
  total_headings: headings.length,
  document_name: doc.name || 'unknown',
  headings: headings,
  has_tables: tables.length > 0,
  has_figures: figures.length > 0
};

return {
  json: {
    status: 'success',
    document_analysis: stats
  }
};
